import { expect, test } from "@e2e/fixtures";
import * as flows from "@e2e/flows";
import * as ui from "@e2e/ui-actions";

test.describe("Copy conversation", () => {
  test("Copy button is visible and enabled after session start", async ({ inspectorPage }) => {
    await test.step("Assert copy button is visible and enabled", async () => {
      await ui.inspectorShell.assertions(inspectorPage).copyButtonIsVisible();
      await ui.inspectorShell.assertions(inspectorPage).copyButtonIsEnabled();
    });
  });

  test("Copy button writes transcript to clipboard", async ({ inspectorPage }) => {
    await test.step("Grant clipboard permissions", async () => {
      await inspectorPage.context().grantPermissions(["clipboard-read", "clipboard-write"], {
        origin: new URL(inspectorPage.url()).origin,
      });
    });

    await flows.chat.sendMessageAndAssertBotReplies(inspectorPage, "Hi there!");

    await test.step("Click copy conversation button", async () => {
      await ui.inspectorShell.actions(inspectorPage).clickCopyConversation();
    });

    await test.step("Assert clipboard contains copied transcript", async () => {
      const clipboardText = await inspectorPage.evaluate(() => navigator.clipboard.readText());
      expect(clipboardText, "Clipboard transcript should contain user message line").toContain(
        "User: Hi there!",
      );
      expect(
        clipboardText,
        "Clipboard transcript should contain at least one agent line",
      ).toContain("Agent:");
    });
  });
});
